// Sources/BdForms/Quiz/BdQuizController.swift, the forms and quiz engine without its SwiftUI
// views. Change it there and regenerate.

import Foundation
import Observation

/// A quiz being taken: the pure engine plus its async parts (BD calls, the
/// clock, autosave). `BdQuiz` draws one; a custom UI can observe `screen`
/// and call the same methods.
///
/// ```swift
/// // A local quiz: the fields carry answer keys, graded on the device.
/// let quiz = BdQuizController(options: BdQuizOptions(fields: fields, feedbackMode: .immediate))
/// ```
@MainActor
@Observable
public final class BdQuizController {
    public private(set) var config: BdQuizConfig
    public private(set) var state: BdQuizState
    /// This device's clock when the screen was last read, epoch ms.
    public private(set) var now: Double

    /// Exactly what the quiz screen shows now.
    public var screen: BdQuizScreen { BdQuizEngine.screen(config, state, now: now) }

    /// Called once, when the quiz ends (scored, submitted, or timed out).
    @ObservationIgnored public var onDone: (@MainActor (BdQuizCompletion) -> Void)?

    @ObservationIgnored private let options: BdQuizOptions
    @ObservationIgnored private let backend: BdQuizBackend?
    @ObservationIgnored private let local: Bool
    @ObservationIgnored private let draftDelay: Duration
    @ObservationIgnored private let clock: @Sendable () -> Double
    @ObservationIgnored private var ticker: Task<Void, Never>?
    @ObservationIgnored private var draftTask: Task<Void, Never>?
    @ObservationIgnored private var lastDraft: [String: BdJSON]
    /// Bumped by a retake: replies to an earlier run are dropped.
    @ObservationIgnored private var generation = 0

    /// - Parameters:
    ///   - backend: BD's side (`BdQuizzes.invitationBackend` /
    ///     `practiceBackend`). Nil for a local run, graded here.
    ///   - initial: where a resumed quiz was left (`BdQuizInitial(invitation:)`).
    ///   - draftDelay: autosave delay for end-feedback answers.
    ///   - clock: this device's clock, epoch ms (a test hook).
    public init(
        options: BdQuizOptions,
        backend: BdQuizBackend? = nil,
        initial: BdQuizInitial = BdQuizInitial(),
        draftDelay: Duration = .milliseconds(750),
        clock: @escaping @Sendable () -> Double = { Date().timeIntervalSince1970 * 1000 }
    ) {
        let local = options.local ?? (backend == nil)
        var resolved = options
        resolved.local = local
        resolved.canRestart = options.canRestart ?? local
        self.options = resolved
        self.backend = backend
        self.local = local
        self.draftDelay = draftDelay
        self.clock = clock
        let now = clock()
        let config = BdQuizConfig(resolved, seed: options.seed ?? BdQuizArrange.randomSeed())
        let state = BdQuizEngine.initialState(config, initial, now: now)
        self.config = config
        self.state = state
        self.now = now
        self.lastDraft = state.answers
        syncClock()
    }

    // MARK: Taking the quiz

    public func setAnswer(_ fieldId: String, _ value: BdJSON) {
        let before = state
        set(BdQuizEngine.setAnswer(config, state, fieldId: fieldId, value: value))
        if state != before { scheduleDraft() }
    }

    /// Pick or unpick a lettered choice: one answer, or toggled in a
    /// multi-select question's list.
    public func choose(_ fieldId: String, _ label: String) {
        guard let field = config.questions.first(where: { $0.id == fieldId }) else { return }
        if BdQuizArrange.isMultiSelect(field) {
            var picked = state.answers[fieldId]?.arrayValue ?? []
            if let i = picked.firstIndex(of: .string(label)) { picked.remove(at: i) } else { picked.append(.string(label)) }
            setAnswer(fieldId, .array(picked))
        } else {
            setAnswer(fieldId, .string(label))
        }
    }

    public func chooseDontKnow(_ fieldId: String) {
        let before = state
        set(BdQuizEngine.chooseDontKnow(config, state, fieldId: fieldId))
        if state != before { scheduleDraft() }
    }

    /// Run a screen action by id (`BdQuizAction.id`). `signIn` is the host's.
    public func perform(_ action: BdQuizActionID) async {
        switch action {
        case .start: await start()
        case .lock, .next, .submit, .finish: await advance()
        case .back: back()
        case .retake: restart()
        case .signIn: break
        }
    }

    /// Start the clock (timed quizzes).
    public func start() async {
        guard state.startedAt == nil, state.pending == nil else { return }
        let run = generation
        var starting = state
        starting.pending = .start
        starting.error = nil
        set(starting)
        do {
            let info = if let start = backend?.start { try await start() } else { BdQuizEngine.localStart(config, now: clock()) }
            if run == generation { set(BdQuizEngine.started(state, info, now: clock())) }
        } catch {
            if run == generation { set(BdQuizEngine.failed(state, Self.message(error, config.words.startFailed))) }
        }
    }

    /// The main button: lock and check, next, or submit.
    public func advance() async {
        let step = BdQuizEngine.advance(config, state, now: clock())
        set(step.state)
        switch step {
        case .lock(_, let fieldId, let answer): await lock(fieldId, answer)
        case .submit(_, let answers): await submit(answers, failure: config.words.submitFailed)
        case .none: break
        }
    }

    public func back() {
        set(BdQuizEngine.back(config, state))
    }

    /// A fresh run (local quizzes): a new order when anything is shuffled.
    public func restart() {
        guard local else { return }
        generation += 1
        draftTask?.cancel()
        draftTask = nil
        config = BdQuizConfig(options, seed: BdQuizArrange.randomSeed())
        now = clock()
        state = BdQuizEngine.initialState(config, BdQuizInitial(), now: now)
        lastDraft = state.answers
        syncClock()
    }

    /// Re-read the clock: update the timer, submit when time is up. Runs on
    /// its own every half second while a timed quiz is under way.
    public func tick() {
        now = clock()
        guard BdQuizEngine.deadlinePassed(config, state, now: now) else { return }
        let answers = state.answers
        set(BdQuizEngine.timeUp(state))
        let saveDraft = config.feedbackMode == .end ? backend?.saveDraft : nil
        Task {
            // The submission carries the answers anyway; the draft is a backstop.
            if let saveDraft { try? await saveDraft(answers) }
            await submit(answers, failure: config.words.timedSubmitFailed)
        }
    }

    /// Stop the clock and autosave, and drop any reply still on its way.
    public func stop() {
        generation += 1
        ticker?.cancel()
        draftTask?.cancel()
        ticker = nil
        draftTask = nil
    }

    // MARK: Internals

    private func set(_ next: BdQuizState) {
        now = clock()
        guard next != state else { return }
        let finished = state.completion == nil && next.completion != nil
        state = next
        syncClock()
        if finished, let completion = next.completion { onDone?(completion) }
    }

    private func syncClock() {
        let running = config.timerEnabled && state.startedAt != nil && state.completion == nil
        if running && ticker == nil {
            ticker = Task { [weak self] in
                while !Task.isCancelled {
                    try? await Task.sleep(for: .milliseconds(500))
                    guard let self, !Task.isCancelled else { return }
                    self.tick()
                }
            }
        } else if !running, let ticker {
            ticker.cancel()
            self.ticker = nil
        }
    }

    private func scheduleDraft() {
        guard let saveDraft = backend?.saveDraft, config.feedbackMode == .end else { return }
        if config.timerEnabled && state.startedAt == nil { return }
        draftTask?.cancel()
        let delay = draftDelay
        draftTask = Task { [weak self] in
            try? await Task.sleep(for: delay)
            guard let self, !Task.isCancelled else { return }
            self.draftTask = nil
            let answers = self.state.answers
            guard answers != self.lastDraft else { return }
            self.lastDraft = answers
            do {
                try await saveDraft(answers)
            } catch {
                var failed = self.state
                failed.error = Self.message(error, self.config.words.draftFailed)
                self.set(failed)
            }
        }
    }

    private func submit(_ answers: [String: BdJSON], failure: String) async {
        draftTask?.cancel()
        draftTask = nil
        let run = generation
        do {
            var completion: BdQuizCompletion
            if let backend {
                completion = try await backend.submit(answers, config.questions.map(\.id))
                // Graded by BD but timed here (a practice run): add the timing.
                if config.local {
                    let timing = BdQuizEngine.localTiming(state, now: clock())
                    if completion.timedOut == nil { completion.timedOut = timing.timedOut }
                    if completion.durationSeconds == nil { completion.durationSeconds = timing.durationSeconds }
                }
            } else {
                completion = BdQuizEngine.localCompletion(config, state, answers: answers, now: clock())
            }
            if run == generation { set(BdQuizEngine.completed(state, completion)) }
        } catch {
            if run == generation { set(BdQuizEngine.failed(state, Self.message(error, failure))) }
        }
    }

    private func lock(_ fieldId: String, _ answer: BdJSON) async {
        let run = generation
        do {
            let result: BdQuizQuestionResult?
            if let backend {
                guard let lockAnswer = backend.lockAnswer else { throw BdFormsError(message: config.words.unscorable) }
                result = try await lockAnswer(fieldId, answer)
            } else {
                result = BdQuizEngine.localResult(config, fieldId: fieldId, answer: answer)
            }
            guard let result else { throw BdFormsError(message: config.words.unscorable) }
            if run == generation {
                set(BdQuizEngine.locked(config, state, fieldId: fieldId, answer: answer, result: result, now: clock()))
            }
        } catch {
            if run == generation { set(BdQuizEngine.failed(state, Self.message(error, config.words.lockFailed))) }
        }
    }

    /// BD's own words when it sent some; otherwise the quiz's.
    static func message(_ error: Error, _ fallback: String) -> String {
        if let error = error as? BdFormsError, !error.message.isEmpty { return error.message }
        return fallback
    }
}
